func fragOf(op, col uint32) runtime.Frag {
	// Bounded by the table, not nCols: existence pseudo-columns live past
	// the real ones. Order, ident and arena lookups stay nCols-bounded,
	// so a pseudo-column can never be ordered by, cursored on, or bound.
	if int(col) >= len(fragTable) || int(op) >= len(fragTable[0]) {
		return runtime.Frag{}
	}
	return fragTable[col][op]
}

// defaultOrder is what a query with no Order() uses.
//
// It is never empty. A read without ORDER BY has no defined order, so
// paging one is a bug waiting for a plan change to expose it — and the
// primary key is the cheapest total order available.
var defaultOrder = [1]runtime.Tok{
	runtime.MakeOrder(runtime.Asc, 0), // id
}

var (
	cache       = runtime.NewTreeCache()
	offsetCache = runtime.NewTreeCache()
	countCache  = runtime.NewTreeCache()
	existsCache = runtime.NewTreeCache()
)

// Shapes reports how many distinct query structures have compiled.
// `raorm lint` uses it to catch a builder minting a statement per request.
func Shapes() int { return cache.Shapes() }

// ShapeFlushes reports how many times a shape cache in this package hit
// runtime.ShapeCap and dropped. Zero is the expected value forever:
// nonzero means a call site is minting structures from request data
// rather than from code, and the fix is that call site, not a bigger
// cap. Export it as a gauge — it is the cheapest early warning that a
// filter screen turned into 2^n statements.
func ShapeFlushes() int {
	return cache.Flushes() + offsetCache.Flushes() +
		countCache.Flushes() + existsCache.Flushes()
}

// stmtFor compiles a read. LIMIT and LIMIT/OFFSET are different
// statements with different placeholder counts, so they get different
// caches rather than a sentinel token muddying the key.
func stmtFor(toks []runtime.Tok, withOffset bool) *runtime.Stmt {
	c, suffix := cache, limitSuffix
	if withOffset {
		c, suffix = offsetCache, limitOffsetSuffix
	}
	if st := c.Get(toks); st != nil {
		return st
	}
	return c.Put(toks, runtime.SpliceTree(selectPrefix, toks, lowering, suffix))
}

// existsStmtFor compiles the existence probe: SELECT 1, no ORDER BY,
// LIMIT 1 — the planner stops at the first matching tuple instead of
// sorting every match to return the "first" of an order nobody reads.
func existsStmtFor(toks []runtime.Tok) *runtime.Stmt {
	if st := existsCache.Get(toks); st != nil {
		return st
	}
	return existsCache.Put(toks, runtime.SpliceTree(existsPrefix, toks, lowering, existsSuffix))
}

func countStmtFor(toks []runtime.Tok) *runtime.Stmt {
	if st := countCache.Get(toks); st != nil {
		return st
	}
	// A count ignores ordering as well as LIMIT: ordering a scalar is
	// wasted work, and the token stream is trimmed before it gets here.
	return countCache.Put(toks, runtime.SpliceTree(countPrefix, toks, lowering, ""))
}

// Composition seams, for the generated CONTEXT package and it alone:
// cross-table statements (a filtered semi-join spans two packages) are
// assembled there from each side's tokens, fragments and bindings. Ids
// only — no SQL text and no value crosses here.

// FragOf is the compiled fragment table, exported for composition.
func FragOf(op, col uint32) runtime.Frag { return fragOf(op, col) }

// Lowering is this package's back-end text, exported for composition.
func Lowering() runtime.Lowering { return lowering }

// StmtPieces are the statement's constant parts, exported for composition.
func StmtPieces() (selectPfx, countPfx, limitSfx string) {
	return selectPrefix, countPrefix, limitSuffix
}

// PredToks appends this query's predicate stream to dst: top-level
// conjuncts reduced to one entry, order excluded.
func (q Query) PredToks(dst []runtime.Tok) []runtime.Tok {
	var buf [21]runtime.Tok
	return append(dst, q.preds(&buf)...)
}

// OrderToks appends this query's ordering — explicit, or the default
// unless Unordered.
func (q Query) OrderToks(dst []runtime.Tok) []runtime.Tok {
	if q.no == 0 {
		if q.noOrder {
			return dst
		}
		return append(dst, defaultOrder[:]...)
	}
	return append(dst, q.otoks[:q.no]...)
}

// BindPreds binds this query's predicate values into b, appending to v.
func (q Query) BindPreds(b *Binder, v []any) []any {
	return append(v, q.bindPreds(b)...)
}

// BindPaging appends the LIMIT (and OFFSET when set) arguments.
func (q Query) BindPaging(b *Binder, v []any) []any {
	b.limit = q.limit
	v = append(v, &b.limit)
	if q.offset > 0 {
		b.offset = q.offset
		v = append(v, &b.offset)
	}
	return v
}

// Shape is a fingerprint of this query's structure — equal shapes share a
// compiled statement. Values do not contribute, which is the point.
func (q Query) Shape() uint64 {
	var buf [21]runtime.Tok
	return runtime.HashToks(q.stream(&buf))
}

// SQL returns the compiled text for this query's structure.
func (q Query) SQL() string {
	var buf [21]runtime.Tok
	return stmtFor(q.stream(&buf), q.offset > 0).SQL
}

// Scan decodes one row from raw wire bytes into r, copying text into sl.
//
// Exported for the context package, which assembles batched results and
// therefore has to decode rows it did not issue the query for.
func Scan(rv [][]byte, r *Row, sl *runtime.Slab) error { return scan(rv, r, sl) }

// scan decodes one row straight from the wire. No reflect, no `any`, no
// driver.Value: the generator knows every column's type already.
//
// It returns an error only for a value the Go type cannot carry — a
// numeric past 18 significant digits, or a NaN. Those must not become a
// plausible zero, and a row scanner is the last place that can tell.
func scan(rv [][]byte, r *Row, sl *runtime.Slab) error {
	var decErr error
	copy(r.ID[:], rv[0])
	r.CreatedAt = runtime.Timestamptz(rv[1])
	r.UpdatedAt = runtime.Timestamptz(rv[2])
	r.On = runtime.Date(rv[3])
	r.Window, decErr = runtime.NullInterval(rv[4])
	if decErr != nil {
		return decErr
	}
	r.Addr, decErr = runtime.InetErr(rv[5])
	if decErr != nil {
		return decErr
	}
	r.Net, decErr = runtime.InetErr(rv[6])
	if decErr != nil {
		return decErr
	}
	r.Tags, decErr = runtime.Int8Array(rv[7])
	if decErr != nil {
		return decErr
	}
	return decErr
}

type binder struct {
	vals   []any
	raws   [4][16]byte
	tims   [4]time.Time
	pfxs   [4]netip.Prefix
	anyRaw [][16]byte
	limit  int64
	offset int64
}

var binders = runtime.NewPool(func() *binder {
	return &binder{vals: make([]any, 0, 17)}
})

// Binder is the pooled argument buffer.
type Binder = binder

func GetBinder() *Binder  { return binders.Get() }
func PutBinder(b *Binder) { putBinder(b) }

// putBinder clears every field that references memory OUTSIDE the binder
// before pooling it. A pooled binder otherwise PINS the caller's data —
// the slice behind an In(...) and the bytes behind every bound string —
// for as long as the pool holds it, which is forever. The numeric, time
// and uuid arenas are value arrays and pin nothing; vals points at the
// binder's own fields. A few nil stores against a round trip is free.
func putBinder(b *binder) {
	b.anyRaw = nil
	binders.Put(b)
}

// bindPreds copies arena values into the pooled buffer and points the
// []any at the buffer's own fields — boxing a pointer does not allocate.
// Count and Exists stop here: their statements carry no LIMIT or OFFSET.
func (q Query) bindPreds(b *binder) []any {
	v := b.vals[:0]
	var nr, ntm, npf uint8
	for i := uint8(0); i < q.nt; i++ {
		t := q.toks[i]
		// KLeaf binds a predicate's value; KCol binds a keyset cursor's.
		// Both live in the same per-type arenas in stream order, so the
		// column switch below handles them identically. A KCol carries no
		// operator — its op is opNone, which matches no case in the
		// operator switch and falls straight through.
		if k := t.Kind(); k != runtime.KLeaf && k != runtime.KCol {
			continue
		}
		switch runtime.Op(t.Op()) {
		case opIsNull, opIsNotNull:
			continue
		case opIn:
			b.anyRaw = q.anyRaw
			v = append(v, &b.anyRaw)
			continue
		}
		switch t.Col() {
		case 0:
			b.raws[nr] = q.raws[nr]
			v = append(v, &b.raws[nr])
			nr++
		case 1:
			b.tims[ntm] = q.tims[ntm]
			v = append(v, &b.tims[ntm])
			ntm++
		case 2:
			b.tims[ntm] = q.tims[ntm]
			v = append(v, &b.tims[ntm])
			ntm++
		case 3:
			b.tims[ntm] = q.tims[ntm]
			v = append(v, &b.tims[ntm])
			ntm++
		case 5:
			b.pfxs[npf] = q.pfxs[npf]
			v = append(v, &b.pfxs[npf])
			npf++
		case 6:
			b.pfxs[npf] = q.pfxs[npf]
			v = append(v, &b.pfxs[npf])
			npf++
		}
	}
	b.vals = v
	return v
}

// bind is bindPreds plus the paging arguments, in suffix order.
func (q Query) bind(b *binder) []any {
	v := q.bindPreds(b)
	b.limit = q.limit
	v = append(v, &b.limit)
	// An offset of zero is absent from the statement, so binding it
	// would leave an argument nothing consumes.
	if q.offset > 0 {
		b.offset = q.offset
		v = append(v, &b.offset)
	}
	b.vals = v
	return v
}

// All runs the query and decodes every row.
func (q Query) All(ctx context.Context, ex runtime.Executor, dst []Row) ([]Row, error) {
	var sl runtime.Slab
	return q.AllInto(ctx, ex, dst, &sl)
}

// AllInto lets the caller own the string arena.
func (q Query) AllInto(ctx context.Context, ex runtime.Executor, dst []Row, sl *runtime.Slab) ([]Row, error) {
	if err := q.Err(); err != nil {
		return dst, err
	}
	var buf [21]runtime.Tok
	st := stmtFor(q.stream(&buf), q.offset > 0)
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return dst, st.Err
	}
	sl.Reserve(st.SlabHint())
	b := binders.Get()
	defer putBinder(b)

	rows, err := ex.Query(ctx, st.SQL, q.bind(b))
	if err != nil {
		return dst, err
	}
	defer rows.Close()
	for rows.Next() {
		dst = append(dst, Row{})
		if err := scan(rows.RawValues(), &dst[len(dst)-1], sl); err != nil {
			return dst, err
		}
	}
	st.ObserveSlab(sl.Size())
	return dst, rows.Err()
}

// One returns the first row, if any.
func (q Query) One(ctx context.Context, ex runtime.Executor) (Row, bool, error) {
	var sl runtime.Slab
	var buf [1]Row
	out, err := q.Limit(1).AllInto(ctx, ex, buf[:0], &sl)
	if err != nil || len(out) == 0 {
		return Row{}, false, err
	}
	return out[0], true, nil
}

// Count ignores Limit: counting a truncated set is a bug, not a feature.
func (q Query) Count(ctx context.Context, ex runtime.Executor) (int64, error) {
	if err := q.Err(); err != nil {
		return 0, err
	}
	var buf [21]runtime.Tok
	st := countStmtFor(q.preds(&buf))
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return 0, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	// bindPreds, not bind: a count has no LIMIT and no OFFSET. The old
	// form bound everything and sliced the last argument off, which was
	// the limit — unless Offset was set, in which case it silently kept
	// the limit and dropped the offset, and the statement mismatched.
	rows, err := ex.Query(ctx, st.SQL, q.bindPreds(b))
	if err != nil {
		return 0, err
	}
	defer rows.Close()
	var n int64
	if rows.Next() {
		n = runtime.Int8(rows.RawValues()[0])
	}
	return n, rows.Err()
}

// Exists asks the one-bit question with a one-bit statement: SELECT 1,
// no ORDER BY, LIMIT 1. It was previously One() with the row thrown
// away, which projected every column AND carried the default ordering —
// measured on 50k rows, the planner top-N-sorted all 16,667 matches to
// return the "first" of an order nobody was going to read.
func (q Query) Exists(ctx context.Context, ex runtime.Executor) (bool, error) {
	if err := q.Err(); err != nil {
		return false, err
	}
	var buf [21]runtime.Tok
	st := existsStmtFor(q.preds(&buf))
	if st.Err != nil {
		return false, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	rows, err := ex.Query(ctx, st.SQL, q.bindPreds(b))
	if err != nil {
		return false, err
	}
	defer rows.Close()
	return rows.Next(), rows.Err()
}

// Prepare resolves the structure and binds arguments without executing.
func (q Query) Prepare(b *Binder) (string, []any) {
	var buf [21]runtime.Tok
	return stmtFor(q.stream(&buf), q.offset > 0).SQL, q.bind(b)
}

// insertSQL does not vary: the column list is fixed by the table, so
// the placeholders are known at build time and nothing is spliced.
const insertSQL = `INSERT INTO "events" ("id", "created_at", "updated_at", "on", "window", "addr", "net", "tags") VALUES ($1, $2, $3, $4, $5, $6, $7, $8) RETURNING "id", "created_at", "updated_at", "on", "window", "addr", "net", "tags"`

const updatePrefix = `UPDATE "events" SET `
const deletePrefix = `DELETE FROM "events"`

// Dirty bits. One per updatable column; the set of them is an UPDATE's
// identity, exactly as a token stream is a SELECT's.
const (
	dUpdatedAt uint64 = 1 << 0
	dOn        uint64 = 1 << 1
	dWindow    uint64 = 1 << 2
	dAddr      uint64 = 1 << 3
	dNet       uint64 = 1 << 4
	dTags      uint64 = 1 << 5
)

const nUpdatable = 6

// setFrags is every assignment this table can make, lowered at build time.
var setFrags = [nUpdatable]runtime.Frag{
	{A: "\"updated_at\" = $", B: ""}, // updated_at
	{A: "\"on\" = $", B: ""},         // on
	{A: "\"window\" = $", B: ""},     // window
	{A: "\"addr\" = $", B: ""},       // addr
	{A: "\"net\" = $", B: ""},        // net
	{A: "\"tags\" = $", B: ""},       // tags
}

// pkFrags addresses one row.
var pkFrags = [1]runtime.Frag{
	{A: "\"id\" = $", B: ""}, // id
}

// Insert bits. A masked INSERT names only the columns the caller
// assigned, so every other column takes its database default — which is
// the only way a DEFAULT gen_random_uuid() can ever fire.
const (
	iID        uint64 = 1 << 0
	iCreatedAt uint64 = 1 << 1
	iUpdatedAt uint64 = 1 << 2
	iOn        uint64 = 1 << 3
	iWindow    uint64 = 1 << 4
	iAddr      uint64 = 1 << 5
	iNet       uint64 = 1 << 6
	iTags      uint64 = 1 << 7
)

const nInsertable = 8

// insCols is the quoted column name for each insert bit.
var insCols = [nInsertable]string{
	"\"id\"",
	"\"created_at\"",
	"\"updated_at\"",
	"\"on\"",
	"\"window\"",
	"\"addr\"",
	"\"net\"",
	"\"tags\"",
}

// insParts and insPlaceholder come from the back end at build time; the
// runtime splicer chooses none of them.
var insParts = runtime.InsertParts{Open: " (", Sep: ", ", Mid: ") VALUES (", Close: ")"}

const insPlaceholder = "$"
const insPrefix = "INSERT INTO \"events\""
const insReturning = " RETURNING \"id\", \"created_at\", \"updated_at\", \"on\", \"window\", \"addr\", \"net\", \"tags\""

var insCache = runtime.NewMaskCache()
var updCache = runtime.NewMaskCache()

// Masks reports how many distinct UPDATE shapes have compiled.
func Masks() int { return updCache.Masks() }

// Mut is a row staged for update: the values, plus which of them were
// actually assigned. An UPDATE writes the assigned ones and no others,
// so a read-modify-write cannot clobber a column it never looked at.
type Mut struct {
	row   Row
	dirty uint64
}

// Mutate stages a row read from the database.
func Mutate(r Row) Mut { return Mut{row: r} }

// Row returns the staged values.
func (m Mut) Row() Row { return m.row }

// Dirty reports the assigned-column mask, which is also the statement key.
func (m Mut) Dirty() uint64 { return m.dirty }

// Setters. There is deliberately no setter for the primary key, for an
// Immutable column, or for the version column: the absence of a method is
// the enforcement, so misuse does not compile rather than failing later.
func (m *Mut) SetUpdatedAt(v time.Time) {
	m.row.UpdatedAt = v
	m.dirty |= dUpdatedAt
}

func (m *Mut) SetOn(v time.Time) {
	m.row.On = v
	m.dirty |= dOn
}

func (m *Mut) SetWindow(v runtime.Interval) {
	m.row.Window = runtime.Null[runtime.Interval]{V: v, Valid: true}
	m.dirty |= dWindow
}

// SetWindowNull writes SQL NULL. It is a separate method because a
// zero value and an absent value are different facts.
func (m *Mut) SetWindowNull() {
	m.row.Window = runtime.Null[runtime.Interval]{}
	m.dirty |= dWindow
}

func (m *Mut) SetAddr(v netip.Prefix) {
	m.row.Addr = v
	m.dirty |= dAddr
}

func (m *Mut) SetNet(v netip.Prefix) {
	m.row.Net = v
	m.dirty |= dNet
}

func (m *Mut) SetTags(v []int64) {
	m.row.Tags = v
	m.dirty |= dTags
}

// Ins stages a new row. Unlike Mut it has a setter for every insertable
// column including the primary key and Immutable ones — supplying your
// own id is legitimate, changing it later is not.
//
// A column left unset is absent from the statement, so the database
// applies its default. Absence is tracked by the mask, never inferred
// from a zero value: that inference is why other ORMs cannot insert a
// false, a 0 or an empty string into a column that has a default.
type Ins struct {
	row Row
	set uint64

	// conflict is the upsert target, as a bit per unique-constraint
	// column set. Zero means a plain insert, and a duplicate is an error
	// — which is the right default: silently updating a row you meant to
	// create is a data-loss bug that looks like success.
	conflict uint8
}

// Create stages a new row.
func Create() Ins { return Ins{} }

// Assigned reports the mask, which is also the statement key.
func (n Ins) Assigned() uint64 { return n.set }

func (n *Ins) SetID(v [16]byte) {
	n.row.ID = v
	n.set |= iID
}

func (n *Ins) SetCreatedAt(v time.Time) {
	n.row.CreatedAt = v
	n.set |= iCreatedAt
}

func (n *Ins) SetUpdatedAt(v time.Time) {
	n.row.UpdatedAt = v
	n.set |= iUpdatedAt
}

func (n *Ins) SetOn(v time.Time) {
	n.row.On = v
	n.set |= iOn
}

func (n *Ins) SetWindow(v runtime.Interval) {
	n.row.Window = runtime.Null[runtime.Interval]{V: v, Valid: true}
	n.set |= iWindow
}

// SetWindowNull writes SQL NULL explicitly, which is not the same as
// leaving the column unset and taking its default.
func (n *Ins) SetWindowNull() {
	n.row.Window = runtime.Null[runtime.Interval]{}
	n.set |= iWindow
}

func (n *Ins) SetAddr(v netip.Prefix) {
	n.row.Addr = v
	n.set |= iAddr
}

func (n *Ins) SetNet(v netip.Prefix) {
	n.row.Net = v
	n.set |= iNet
}

func (n *Ins) SetTags(v []int64) {
	n.row.Tags = v
	n.set |= iTags
}

// upsertTails builds the ON CONFLICT tail for one target, given the
// insert mask — an upsert must only overwrite the columns the caller
// assigned, or it silently reverts every column it did not.
var upsertTails = []func(uint64) string{
	func(mask uint64) string {
		set := make([]string, 0, 6)
		if mask&(1<<2) != 0 {
			set = append(set, "updated_at")
		}
		if mask&(1<<3) != 0 {
			set = append(set, "on")
		}
		if mask&(1<<4) != 0 {
			set = append(set, "window")
		}
		if mask&(1<<5) != 0 {
			set = append(set, "addr")
		}
		if mask&(1<<6) != 0 {
			set = append(set, "net")
		}
		if mask&(1<<7) != 0 {
			set = append(set, "tags")
		}
		return onConflictID(set)
	},
}

func onConflictID(set []string) string {
	switch len(set) {
	case 0:
		return " ON CONFLICT (\"id\") DO NOTHING"
	}
	return " ON CONFLICT (\"id\") DO UPDATE SET " + joinAssign(set)
}

// OnConflictID upserts on the unique key (id).
func (n *Ins) OnConflictID() *Ins {
	n.conflict = 1
	return n
}

// joinAssign renders the DO UPDATE SET list for the columns the caller
// assigned. The punctuation comes from the back end, never from here.
func joinAssign(set []string) string {
	out := ""
	for i, c := range set {
		if i > 0 {
			out += ", "
		}
		out += assignExcluded(c)
	}
	return out
}

var assignFor = map[string]string{
	"updated_at": "\"updated_at\" = EXCLUDED.\"updated_at\"",
	"on":         "\"on\" = EXCLUDED.\"on\"",
	"window":     "\"window\" = EXCLUDED.\"window\"",
	"addr":       "\"addr\" = EXCLUDED.\"addr\"",
	"net":        "\"net\" = EXCLUDED.\"net\"",
	"tags":       "\"tags\" = EXCLUDED.\"tags\"",
}

func assignExcluded(c string) string { return assignFor[c] }

func stmtForInsert(mask uint64, conflict uint8) *runtime.Stmt {
	// The conflict target is part of the statement, so it must be part of
	// the key. Packing it above the column bits keeps one cache for both.
	key := mask | uint64(conflict)<<nInsertable
	if st := insCache.Get(key); st != nil {
		return st
	}
	cols := make([]string, 0, nInsertable)
	for i := 0; i < nInsertable; i++ {
		if mask&(1<<uint(i)) != 0 {
			cols = append(cols, insCols[i])
		}
	}
	suffix := insReturning
	if conflict > 0 {
		suffix = upsertTails[conflict-1](mask) + insReturning
	}
	return insCache.Put(key, runtime.SpliceInsert(insPrefix, insParts, cols, insPlaceholder, suffix))
}

// Insert writes the assigned columns and reads every column back, so
// database-computed values land in the returned Row rather than needing a
// second SELECT that would race every other writer.
func (n *Ins) Insert(ctx context.Context, ex runtime.Executor) (Row, error) {
	if n.set == 0 {
		return Row{}, runtime.ErrNothingAssigned
	}
	st := stmtForInsert(n.set, n.conflict)
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return Row{}, st.Err
	}
	args := make([]any, 0, st.NArg)
	for i := 0; i < nInsertable; i++ {
		if n.set&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, n.row.ID)
		case 1:
			args = append(args, n.row.CreatedAt)
		case 2:
			args = append(args, n.row.UpdatedAt)
		case 3:
			args = append(args, n.row.On)
		case 4:
			args = append(args, n.row.Window.Arg())
		case 5:
			args = append(args, n.row.Addr)
		case 6:
			args = append(args, n.row.Net)
		case 7:
			args = append(args, n.row.Tags)
		}
	}
	var out Row
	rows, err := ex.Query(ctx, st.SQL, args)
	if err != nil {
		return out, err
	}
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return out, err
		}
		return out, runtime.ErrNoRow
	}
	var sl runtime.Slab
	if err := scan(rows.RawValues(), &out, &sl); err != nil {
		return out, err
	}
	return out, rows.Err()
}

// Inserts reports how many distinct INSERT column sets have compiled.
func Inserts() int { return insCache.Masks() }

// Insert writes one row and reads back every column, so database-computed
// defaults — a generated id, a now() timestamp — land in r rather than
// needing a second SELECT that would race every other writer.
//
// Every insertable column is written, including zero values. raorm does
// not treat a zero as 'unset': that guess is why other ORMs cannot insert
// a false, a 0 or an empty string into a column with a default.
func Insert(ctx context.Context, ex runtime.Executor, r *Row) error {
	args := make([]any, 0, 8)
	args = append(args, r.ID)
	args = append(args, r.CreatedAt)
	args = append(args, r.UpdatedAt)
	args = append(args, r.On)
	args = append(args, r.Window.Arg())
	args = append(args, r.Addr)
	args = append(args, r.Net)
	args = append(args, r.Tags)
	rows, err := ex.Query(ctx, insertSQL, args)
	if err != nil {
		return err
	}
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return err
		}
		return runtime.ErrNoRow
	}
	// The returned strings live as long as this Slab, and the Slab lives
	// as long as r — a Row from an insert owns its own arena, unlike a Row
	// from a scan, which shares the result set's.
	var sl runtime.Slab
	if err := scan(rows.RawValues(), r, &sl); err != nil {
		return err
	}
	return rows.Err()
}

// copyCols is the fixed column list of a bulk load. Unlike Ins there is
// no mask: COPY sends one shape for the whole stream, so every row must
// supply every column and database defaults do not apply. Fill the row
// yourself, or use Create() per row and give up the bulk path.
var copyCols = []string{
	"id",
	"created_at",
	"updated_at",
	"on",
	"window",
	"addr",
	"net",
	"tags",
}

// rowSource walks a []Row for CopyFrom without copying any of it.
type rowSource struct {
	rows []Row
	i    int
	buf  [8]any
}

func (s *rowSource) Next() bool {
	s.i++
	return s.i <= len(s.rows)
}

// Values reuses one buffer across every row, and fills it with POINTERS
// into the caller's slice rather than copies.
//
// Both halves matter. The driver consumes each slice before asking for
// the next, so one buffer is safe. And boxing a pointer into an `any`
// does not allocate while boxing a value does — at a thousand rows that
// is one allocation per column per row, or none. Measured: the first cut
// boxed values and cost 7 allocations per row.
func (s *rowSource) Values() []any {
	r := &s.rows[s.i-1]
	s.buf[0] = &r.ID
	s.buf[1] = &r.CreatedAt
	s.buf[2] = &r.UpdatedAt
	s.buf[3] = &r.On
	s.buf[4] = r.Window.Ptr()
	s.buf[5] = &r.Addr
	s.buf[6] = &r.Net
	s.buf[7] = &r.Tags
	return s.buf[:]
}

func (s *rowSource) Err() error { return nil }

// InsertAll bulk-loads rows through the driver's COPY protocol: ONE round
// trip regardless of row count, because COPY is a different wire path and
// not a faster loop over INSERT.
//
// It returns no rows. COPY has no RETURNING, so a caller who needs
// database-generated ids must supply them — which is why the primary key
// is in copyCols and must be set on every row.
func InsertAll(ctx context.Context, ex runtime.Executor, rows []Row) (int64, error) {
	if len(rows) == 0 {
		return 0, nil
	}
	src := &rowSource{rows: rows}
	return ex.CopyFrom(ctx, "events", copyCols, src)
}

// InsertOp is an insert as a queueable statement. It writes every
// insertable column, because a batch of a thousand rows that each chose
// a different column set would compile a thousand statements and defeat
// the point of batching them.
//
// WantRows is false: a batched insert reports a count. Asking for
// RETURNING here would mean scanning a result per statement, which is
// exactly the per-row work a batch exists to avoid.
func InsertOp(r Row) runtime.BatchOp {
	var mask uint64
	mask |= 1 << 0
	mask |= 1 << 1
	mask |= 1 << 2
	mask |= 1 << 3
	mask |= 1 << 4
	mask |= 1 << 5
	mask |= 1 << 6
	mask |= 1 << 7
	st := stmtForInsert(mask, 0)
	args := make([]any, 0, 8)
	args = append(args, r.ID)
	args = append(args, r.CreatedAt)
	args = append(args, r.UpdatedAt)
	args = append(args, r.On)
	args = append(args, r.Window.Arg())
	args = append(args, r.Addr)
	args = append(args, r.Net)
	args = append(args, r.Tags)
	return runtime.BatchOp{SQL: st.SQL, Args: args}
}

// UpdateOp is this Mut's update as a queueable statement.
//
// The optimistic lock still applies, but the caller must check the
// affected count the batch reports: a stale write inside a batch is not
// an error the driver raises, it is a zero the caller has to notice.
func (m *Mut) UpdateOp() (runtime.BatchOp, bool) {
	if m.dirty == 0 {
		return runtime.BatchOp{}, false
	}
	st := stmtForMask(m.dirty)
	args := make([]any, 0, st.NArg)
	for i := 0; i < nUpdatable; i++ {
		if m.dirty&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, m.row.UpdatedAt)
		case 1:
			args = append(args, m.row.On)
		case 2:
			args = append(args, m.row.Window.Arg())
		case 3:
			args = append(args, m.row.Addr)
		case 4:
			args = append(args, m.row.Net)
		case 5:
			args = append(args, m.row.Tags)
		}
	}
	args = append(args, m.row.ID)
	return runtime.BatchOp{SQL: st.SQL, Args: args}, true
}

// DeleteOp is a delete as a queueable statement.
func DeleteOp(iD [16]byte) runtime.BatchOp {
	return runtime.BatchOp{SQL: deleteSQL, Args: []any{iD}}
}

// Table is the table these statements write, so a Unit can order a mixed
// batch by foreign key without knowing what any of them are.
const Table = "events"

// stmtForMask compiles the UPDATE for one dirty mask, once.
func stmtForMask(mask uint64) *runtime.Stmt {
	if st := updCache.Get(mask); st != nil {
		return st
	}
	set := make([]runtime.Frag, 0, nUpdatable+1)
	for i := 0; i < nUpdatable; i++ {
		if mask&(1<<uint(i)) != 0 {
			set = append(set, setFrags[i])
		}
	}
	where := make([]runtime.Frag, 0, 2)
	where = append(where, pkFrags[:]...)
	return updCache.Put(mask, runtime.SpliceSections(updatePrefix, []runtime.Section{
		{Lead: "", Sep: ", ", Frags: set},
		{Lead: " WHERE ", Sep: " AND ", Frags: where},
	}, ""))
}

// Update writes the assigned columns of one row.
//
// Assigning nothing is not an error and issues no statement — an UPDATE
// with an empty SET list is not valid SQL, and a caller looping over
// possibly-changed fields should not have to special-case the empty case.
func (m *Mut) Update(ctx context.Context, ex runtime.Executor) error {
	if m.dirty == 0 {
		return nil
	}
	st := stmtForMask(m.dirty)
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return st.Err
	}
	args := make([]any, 0, st.NArg)
	for i := 0; i < nUpdatable; i++ {
		if m.dirty&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, m.row.UpdatedAt)
		case 1:
			args = append(args, m.row.On)
		case 2:
			args = append(args, m.row.Window.Arg())
		case 3:
			args = append(args, m.row.Addr)
		case 4:
			args = append(args, m.row.Net)
		case 5:
			args = append(args, m.row.Tags)
		}
	}
	args = append(args, m.row.ID)
	n, err := ex.Exec(ctx, st.SQL, args)
	if err != nil {
		return err
	}
	if n == 0 {
		return runtime.ErrNoRow
	}
	m.dirty = 0
	return nil
}

var deleteSQL = runtime.SpliceSections(deletePrefix, []runtime.Section{
	{Lead: " WHERE ", Sep: " AND ", Frags: pkFrags[:]},
}, "").SQL

// Delete removes one row by primary key. A row that was already gone is
// runtime.ErrNoRow, not success: a caller deleting something that is not
// there usually has a bug, and swallowing it hides the bug.
func Delete(ctx context.Context, ex runtime.Executor, iD [16]byte) error {
	n, err := ex.Exec(ctx, deleteSQL, []any{iD})
	if err != nil {
		return err
	}
	if n == 0 {
		return runtime.ErrNoRow
	}
	return nil
}
